const promo = new Map<string, number>([["HEMAT10", 10], ["MURAH5", 5]]);
const kode: string | undefined = undefined;
const persen = (kode !== undefined ? promo.get(kode) : undefined) ?? 0;
console.log("Diskon:", persen, "persen");

const promo = new Map<string, number>([["HEMAT10", 10], ["MURAH5", 5]]);
const belanja = 40000;
const persen = promo.get("HEMAT10") ?? 0;
console.log("Potongan:", (belanja * persen) / 100);

